// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller and the sent amount. The general rule: the reference contract only accepts exactly 10 ether,
    // so for any input other than exactly 10 ether the call reverts and pastBlockTime remains its previous value.
    // The mutant accepts >=10 ether so for amounts >10 ether the mutant can succeed while the reference reverts,
    // causing pastBlockTime to change in the mutant but not in the reference. We expose this by asserting that
    // after attempting a fallback call with an arbitrary amount from an arbitrary actor, either the call reverted
    // (so pastBlockTime unchanged) OR, if it succeeded, pastBlockTime is strictly greater than its previous value.
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        // keep the domain wide; allow any amount up to a large bound
        amount = bound(amount, 0, 100 ether);

        // record previous value
        uint256 prev = c.pastBlockTime();

        // fund actor and perform the call
        vm.deal(actor, amount);
        bool ok;
        vm.prank(actor);
        try c.f{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if call succeeded, pastBlockTime must now be > prev; if call reverted, pastBlockTime must equal prev.
        // This holds for the reference (only amount == 10 ether can succeed, and then pastBlockTime increases). The mutant
        // allows success for amount > 10 ether, so there exist inputs where ok == true but prev was not increased by the reference
        // (i.e., the reference would have reverted) — the fuzzer will find such an input and cause the mutant to differ.
        if (ok) {
            assertTrue(c.pastBlockTime() > prev);
        } else {
            assertTrue(c.pastBlockTime() == prev);
        }
    }
}

