    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor usable and amount within a wide but sensible range
        vm.assume(actor != address(0));
        // bound amount to reasonable maximum to avoid overflow in vm.deal
        amount = bound(amount, 0, 100 ether);

        // fund the actor so it can send the amount
        vm.deal(actor, amount);

        bool ok;
        // make the call as the actor and capture whether it succeeded
        vm.prank(actor);
        try c.fallback{value: amount}() {
            ok = true;
