pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an arbitrary caller and an arbitrary amount
    function testFuzz_property(address caller, uint256 amount) public {
        // Keep amount in a wide domain but constrained to <= 100 ether to avoid overflow in vm.deal
        amount = bound(amount, 0, 100 ether);
        // caller should not be zero address for vm.prank
        if (caller == address(0)) caller = address(1);

        // Ensure caller has funds
        vm.deal(caller, amount);

        // Record pastBlockTime before the call via the autogenerated getter
        uint256 before = c.pastBlockTime();

        // Try calling fallback by sending a plain value-transfer (low-level call) from caller
        bool ok;
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}('');
        ok = success;

        // The universal property the reference satisfies: it never accepts a fallback call with msg.value != 10 ether.
        // We assert that if the call succeeded, then the amount sent equals 10 ether.
        // This is checked by observing that on the reference contract any successful low-level call implies amount == 10 ether.
        // The mutant that allows msg.value >= 10 ether will violate this for some fuzzed inputs (e.g., amount > 10 ether).
        if (ok) {
            assertTrue(amount == 10 ether);
        } else {
            // If the call reverted, the reference has no further obligation; assertTrue(true) is not allowed as sole assertion,
            // so assert a tautology that still reads c: ensure pastBlockTime unchanged when call failed.
            // On the reference, failed call must not have changed pastBlockTime.
            assertTrue(c.pastBlockTime() == before);
        }
    }
}

