pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller address and a timestamp to warp to
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller non-zero and ts in a wide but practical range
        vm.assume(caller != address(0));
        ts = bound(ts, 0, type(uint64).max);

        // initial funding so contract can receive and possibly pay out
        vm.deal(caller, 20 ether);

        // establish an initial pastBlockTime by performing a valid call at an earlier timestamp
        vm.warp(1);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // record the stored pastBlockTime after that first call
        uint256 before = c.pastBlockTime();

        // warp to the fuzzed timestamp and perform the second call
        vm.warp(ts);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // The general property: the reference only updates pastBlockTime when block.timestamp > before.
        // Therefore, after the second call, either block.timestamp was not greater and pastBlockTime stayed equal to `before`,
        // or block.timestamp was greater and pastBlockTime equals block.timestamp + 1.
        // The single assert reads c's public getter to check that one of these holds.
        uint256 after = c.pastBlockTime();

        bool ok = (ts <= before ? after == before : after == ts + 1);
        assertTrue(ok);
    }
}

