import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and a boolean that decides whether we warp time forward
    function testFuzz_property(address caller, bool advanceTime) public {
        // Keep caller non-zero
        vm.assume(caller != address(0));

        // fund the caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // Step 1: make an initial successful call to set pastBlockTime to some value
        // Use caller as the msg.sender via prank
        vm.prank(caller);
        // call fallback with exactly 10 ether
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1); // initial call must succeed

        // read the stored pastBlockTime after first call
        uint256 before = c.pastBlockTime();

        // Optionally do NOT advance block.timestamp to create the adversarial case
        if (advanceTime) {
            // move time forward by 100 seconds to ensure block.timestamp > before-1
            vm.warp(block.timestamp + 100);
        } else {
            // keep timestamp the same (no warp)
        }

        // Step 2: second call from same caller sending exactly 10 ether again
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);

        // After the second call, in the correct contract pastBlockTime should only change if block.timestamp > previous stored value.
        // We assert the universal property: if block.timestamp <= before-1 then pastBlockTime must remain equal to "before";
        // equivalently, if block.timestamp <= before-1 then pastBlockTime cannot become equal to block.timestamp+1 (which would be <= before).
        uint256 after = c.pastBlockTime();

        // The single required assertion: for the reference contract, if current block.timestamp <= before-1 then pastBlockTime was NOT overwritten to a value <= before-1.
        // We express this as: if block.timestamp <= before-1 then after >= before.
        if (block.timestamp <= before - 1) {
            assertTrue(after >= before);
        } else {
            // If time advanced, the reference may update; still assert something always true: after >= before (monotonic non-decrease when time advanced)
            // This keeps the assertion universal for the reference while the mutant can break it when time did NOT advance.
            assertTrue(after >= before);
        }
    }
}

