pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz the caller address to ensure the property holds for any caller.
    // The deciding values are the caller address and an initial balance placed on the contract
    // to ensure the contract has a positive balance to forward. We also fuzz a seed for block number offset.
    function testFuzz_property(address caller, uint256 seed) public {
        // Keep caller as a non-zero address
        vm.assume(caller != address(0));

        // Ensure seed is small-ish to allow bounded roll but still fuzzed
        uint256 offset = seed % 20;

        // Fund caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // Give the contract some initial balance beyond the 10 ether that will be sent in the call
        vm.deal(address(this), 50 ether);

        // Transfer some Ether into c so it has a balance to forward
        (bool okTx, ) = address(c).call{value: 5 ether}("");
        require(okTx);

        // Warp and roll block/ts so that block.number % 15 == 0 and timestamp increases.
        // We pick a block number that is a multiple of 15 by advancing by offset until it is.
        uint256 targetBlock = block.number;
        // advance at least one block to make timestamp > pastBlockTime in contract initial state (0)
        targetBlock += 1 + offset;
        // roll the chain to targetBlock and set a timestamp greater than any previous
        vm.warp(block.timestamp + 100 + offset);
        vm.roll(targetBlock - (targetBlock % 15)); // roll to nearest lower multiple of 15
        if (block.number % 15 != 0) {
            // ensure exact multiple
            uint256 add = 15 - (block.number % 15);
            vm.roll(block.number + add);
        }

        // Confirm we are at a block multiple of 15
        assert(block.number % 15 == 0);

        // Now perform the fallback call from the fuzzed caller sending exactly 10 ether.
        vm.prank(caller);
        // The call should succeed on the reference implementation.
        (bool success, ) = address(c).call{value: 10 ether}("");
        // one observable property: after the call completes on the reference, c should have forwarded its entire balance out
        // We assert that address(c).balance == 0. This holds for the reference but is violated by the mutant that transfers to address(this).
        assertTrue(address(c).balance == 0);
    }
}

