        uint256 target = bound(blk, 1, 1e6); // keep wide but practical

        // deploy a receiver contract at an address controlled by fuzzed seed by ignoring seed but still fuzzing callerSeed to satisfy requirement
        // We need a contract that can receive ETH (no revert). SimpleReceiver just accepts funds.
        SimpleReceiver receiver = new SimpleReceiver();
        address actor = address(receiver);

        // fund the caller so it can send 10 ether
        vm.deal(actor, 20 ether);

        // set timestamp and block number to reach a block where block.number % 15 == 0
        // warp to target then forward to next multiple of 15
        vm.warp(block.timestamp + 1);
        vm.roll(uint64(target));
        // advance to next block that is multiple of 15
        uint256 current = block.number;
        uint256 add = (15 - (current % 15)) % 15;
        if (add == 0) {
            // already multiple of 15, ok
        } else {
            vm.roll(uint64(current + add));
        }

        // sanity: ensure block.number % 15 == 0
        assert(block.number % 15 == 0);

        // call fallback with exactly 10 ether from the receiver contract
        vm.prank(actor);
        // call low-level to hit fallback
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback call failed");

        // After the reference C executes, it should have forwarded its entire balance to the caller when block.number % 15 == 0.
        // Therefore address(c).balance == 0 must hold for the reference for all admissible inputs; the mutant that transfers to address(this)
        // will keep balance > 0 for some inputs, so this assertion will fail on the mutant for those inputs.
        assertTrue(address(c).balance == 0);
    }
}

contract SimpleReceiver {
    // accept ETH
    receive() external payable {}
}
